/**
 * Maps the mentions in `body` onto the ids of members who actually exist.
 * Every active member matches, whatever their role. A handle shared by
 * several members mentions all of them. Unknown handles are silently dropped
 * — a typo must never fail the comment write. The comment's author is left
 * for the caller to drop; this function only resolves the text.
 */
export function resolveMentions(
  body: string,
  members: readonly MemberWithUser[],
): readonly UserId[] {
  const byHandle = new Map<string, UserId[]>();
  for (const member of members) {
    if (member.status !== "active" || member.archivedAt !== null) continue;
    const handle = handleOf(member);
    if (handle === "") continue;
    const ids = byHandle.get(handle);
    if (ids === undefined) {
      byHandle.set(handle, [member.userId]);
    } else if (!ids.includes(member.userId)) {
      ids.push(member.userId);
    }
  }

  const resolved: UserId[] = [];
  const seen = new Set<UserId>();
  for (const handle of extractMentions(body)) {
    for (const userId of byHandle.get(handle) ?? []) {
      if (seen.has(userId)) continue;
      seen.add(userId);
      resolved.push(userId);
    }
  }

  return resolved;
}

