/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first and, under each one, every reply that descends from it — directly or
 * through other replies — in posting order. A deleted comment stays in place
 * as a placeholder with its text removed, so the replies under it stay put.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(comments.id))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  return assembleThread(decorated);
}

function assembleThread(
  commentsInOrder: readonly CommentWithAuthor[],
): readonly CommentThreadNode[] {
  const byId = new Map(commentsInOrder.map((comment) => [comment.id, comment]));
  const repliesBy = new Map<string, CommentWithAuthor[]>();
  const roots: CommentWithAuthor[] = [];

  for (const comment of commentsInOrder) {
    const root = rootOf(comment, byId);
    if (root.id === comment.id) {
      roots.push(comment);
      continue;
    }
    const bucket = repliesBy.get(root.id) ?? [];
    bucket.push(comment);
    repliesBy.set(root.id, bucket);
  }

  return roots.map((comment) => ({
    comment: withoutDeletedText(comment),
    replies: (repliesBy.get(comment.id) ?? []).map(withoutDeletedText),
  }));
}

/** Walks parent links to the top-level comment. A missing parent stops the walk. */
function rootOf(
  comment: CommentWithAuthor,
  byId: ReadonlyMap<string, CommentWithAuthor>,
): CommentWithAuthor {
  let current = comment;
  const seen = new Set<string>();

  while (current.parentId !== null) {
    if (seen.has(current.id)) break;
    seen.add(current.id);
    const parent = byId.get(current.parentId);
    if (parent === undefined) break;
    current = parent;
  }

  return current;
}

/** A deleted comment keeps its place but no longer carries its text. */
function withoutDeletedText(comment: CommentWithAuthor): CommentWithAuthor {
  if (comment.archivedAt === null) return comment;
  return { ...comment, body: "" };
}

