subscribe("comment.created", async (payload) => {
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  const comment = await commentRepo.findCommentById(
    payload.orgId,
    payload.commentId,
  );

  const mentioned = new Set(payload.mentionedUserIds);
  const watchers = new Set<UserId>();
  if (issue) {
    watchers.add(issue.authorId);
    if (issue.assigneeId !== null) watchers.add(issue.assigneeId);
  }
  if (comment?.parentId) {
    const parent = await commentRepo.findCommentById(
      payload.orgId,
      comment.parentId,
    );
    if (parent) watchers.add(parent.authorId);
  }
  if (comment) watchers.delete(comment.authorId);
  if (payload.actorId !== null) watchers.delete(payload.actorId);
  for (const userId of mentioned) watchers.delete(userId);

  await notify(payload.orgId, "comment_created", [...watchers], {
    title: "New comment",
    body: `A comment was added to issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });

  if (payload.mentionedUserIds.length > 0) {
    await notify(
      payload.orgId,
      "comment_mention",
      payload.mentionedUserIds,
      {
        title: "You were mentioned",
        body: `You were mentioned on issue ${payload.issueId}`,
        href: `/issues/${payload.issueId}`,
        actorId: payload.actorId,
      },
    );
  }
});

subscribe("comment.updated", async (payload) => {
  const already = new Set(payload.previousMentionedUserIds);
  const newlyMentioned = payload.mentionedUserIds.filter(
    (userId) => !already.has(userId),
  );
  if (newlyMentioned.length === 0) return;

  await notify(payload.orgId, "comment_mention", newlyMentioned, {
    title: "You were mentioned",
    body: `You were mentioned on issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });
});

